'use strict';

// MODULES //

var tape = require( 'tape' );
var hasSymbolSupport = require( '@stdlib/assert/has-symbol-support' );
var Symbol = require( '@stdlib/symbol/ctor' );
var polyfill = require( './../lib/polyfill.js' );


// VARIABLES //

var opts = {
	'skip': !hasSymbolSupport()
};


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof polyfill, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `false` if provided `null` or `undefined`', function test( t ) {
	var bool;

	bool = polyfill( null, 'a' );
	t.strictEqual( bool, false, 'returns false when null' );

	bool = polyfill( void 0, 'a' );
	t.strictEqual( bool, false, 'returns false when undefined' );

	t.end();
});

tape( 'the function returns `true` if an object property is enumerable', function test( t ) {
	var bool;
	var obj;

	obj = {
		'a': 'b',
		'c': 1
	};
	bool = polyfill( obj, 'a' );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = polyfill( obj, 'c' );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = polyfill( [ 1, 2, 3 ], '1' );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = polyfill( [ 1, 2, 3 ], 1 );
	t.strictEqual( bool, true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `false` if an object property is not enumerable', function test( t ) {
	var bool;
	var obj;

	obj = {
		'a': 'b'
	};
	bool = polyfill( obj, 'c' );
	t.strictEqual( bool, false, 'returns expected value' );

	bool = polyfill( [ 'a' ], 'length' );
	t.strictEqual( bool, false, 'returns expected value' );

	t.end();
});

tape( 'the function returns `false` if provided an inherited property', function test( t ) {
	var bool;

	bool = polyfill( {}, 'hasOwnProperty' );
	t.strictEqual( bool, false, 'returns expected value' );

	bool = polyfill( {}, 'toString' );
	t.strictEqual( bool, false, 'returns expected value' );

	bool = polyfill( {}, 'constructor' );
	t.strictEqual( bool, false, 'returns expected value' );

	t.end();
});

tape( 'the function returns `true` for enumerable string indices', function test( t ) {
	var bool;

	bool = polyfill( 'beep', '1' );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = polyfill( 'beep', 1 );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = polyfill( 'beep', 'length' );
	t.strictEqual( bool, false, 'returns expected value' );

	bool = polyfill( 'beep', '10' );
	t.strictEqual( bool, false, 'returns expected value' );

	t.end();
});

tape( 'the function coerces property values to strings', function test( t ) {
	var bool;
	var obj;

	obj = {
		'null': true,
		'[object Object]': true
	};
	bool = polyfill( obj, null );
	t.strictEqual( bool, true, 'returns expected value' );

	bool = polyfill( obj, {} );
	t.strictEqual( bool, true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `false` when provided a symbol', opts, function test( t ) {
	var bool;

	bool = polyfill( {}, Symbol( 'a' ) );
	t.strictEqual( bool, false, 'returns expected value' );
	t.end();
});
